'use client';

import { useMemo, useSyncExternalStore } from 'react';

const subscribe = () => () => {};

/**
 * Prefer a nonce generated by the Server Component. Legacy call-sites that do
 * not yet provide one stay hydration-safe: SSR and hydration both expose null,
 * then React switches to the browser snapshot containing this component's
 * stable nonce. Callers must not enable their command form until a nonce is
 * returned.
 */
export function useResolvedCommandNonce(serverNonce?: string): string | null {
  const browserNonce = useMemo(() => crypto.randomUUID(), []);

  return useSyncExternalStore(
    subscribe,
    () => serverNonce ?? browserNonce,
    () => serverNonce ?? null,
  );
}
